begin;
set local role service_role;
select current_user;
select id,student_id,'Sin contrato demostrable; requiere revisión' motivo from public.enrollments where status='activo' and (practice_plan is null or not(practice_plan ?& array['fechaFinElegida','modalidad','horasPorDia']));
do $$begin if not has_function_privilege('service_role','private.practice_block_options_v14(uuid,date)','EXECUTE') or (select prosecdef from pg_proc where oid='private.practice_block_options_v14(uuid,date)'::regprocedure) then raise exception 'VERIFICACION_089: seguridad incorrecta de private.practice_block_options_v14(uuid,date)';end if;end $$;
do $$begin if not has_function_privilege('service_role','private.practice_block_v14(uuid,uuid,date)','EXECUTE') or (select prosecdef from pg_proc where oid='private.practice_block_v14(uuid,uuid,date)'::regprocedure) then raise exception 'VERIFICACION_089: seguridad incorrecta de private.practice_block_v14(uuid,uuid,date)';end if;end $$;
