do $$begin if not has_function_privilege('service_role','private.notify_released_block_v14(uuid)','EXECUTE') or (select prosecdef from pg_proc where oid='private.notify_released_block_v14(uuid)'::regprocedure) then raise exception 'VERIFICACION_089: seguridad incorrecta de private.notify_released_block_v14(uuid)';end if;end $$;
do $$begin if not has_function_privilege('service_role','cancel_practice_block_with_reason_v14(uuid,uuid,date,text,text)','EXECUTE') or (select prosecdef from pg_proc where oid='cancel_practice_block_with_reason_v14(uuid,uuid,date,text,text)'::regprocedure) then raise exception 'VERIFICACION_089: seguridad incorrecta de cancel_practice_block_with_reason_v14(uuid,uuid,date,text,text)';end if;end $$;
do $$begin if not has_function_privilege('service_role','confirm_practice_block_v14(uuid,uuid,date)','EXECUTE') or (select prosecdef from pg_proc where oid='confirm_practice_block_v14(uuid,uuid,date)'::regprocedure) then raise exception 'VERIFICACION_089: seguridad incorrecta de confirm_practice_block_v14(uuid,uuid,date)';end if;end $$;
rollback;
